package main

import (
 "encoding/json"
 "os"
 "runtime/debug"
 "time"

 "github.com/Vadman97/GolangChessAI/pkg/chessai/analysis"
 "github.com/Vadman97/GolangChessAI/pkg/chessai/board"
 "github.com/Vadman97/GolangChessAI/pkg/chessai/color"
 "github.com/Vadman97/GolangChessAI/pkg/chessai/player/ai"
)

type Case struct {
 ID string `json:"id"`
 Prefix []string `json:"prefix"`
 Opening int `json:"opening"`
 BudgetMs int `json:"budgetMs"`
}

func main() {
 debug.SetGCPercent(400)
 debug.SetMemoryLimit(2 << 30)
 var c Case
 if err:=json.NewDecoder(os.Stdin).Decode(&c);err!=nil {panic(err)}
 b:=&board.Board{}
 b.ResetDefault()
 b.CacheGetAllMoves=false
 b.CacheGetAllAttackableMoves=false
 var previous *board.LastMove
 for i,uci:=range c.Prefix {
  move,err:=analysis.MatchUCIMove(b,color.Color(i%2),previous,uci);if err!=nil {panic(err)}
  previous=board.MakeMove(&move,b)
 }
 side:=color.Color(len(c.Prefix)%2)
 algorithm:=&ai.ABDADA{NumThreads:4}
 p:=ai.NewAIPlayer(side,algorithm)
 p.Opening=c.Opening
 p.TurnCount=len(c.Prefix)/2
 p.MaxSearchDepth=64
 p.MaxThinkTime=time.Duration(c.BudgetMs)*time.Millisecond
 p.Debug=false
 p.PrintInfo=false
 fen:=analysis.BoardToFEN(b,side,previous,len(c.Prefix)/2+1)
 start:=time.Now()
 move:=p.GetBestMove(b,previous,nil)
 row:=map[string]any{"id":c.ID,"prefix":c.Prefix,"opening":c.Opening,"budgetMs":c.BudgetMs,"fen":fen,"move":analysis.MoveToUCI(*move),"depth":p.LastSearchDepth,"elapsedMs":time.Since(start).Milliseconds(),"nodes":p.Metrics.MovesConsidered,"openingAfter":p.Opening}
 if err:=json.NewEncoder(os.Stdout).Encode(row);err!=nil {panic(err)}
}

