import hashlib,json,subprocess
from pathlib import Path
prefix='/tmp/chess-oct26-opening-policy'
binaries={'before':'/tmp/chess-oct26-opening-policy-before','after':'/tmp/chess-oct26-opening-policy-after'}
def digest(path):return hashlib.sha256(Path(path).read_bytes()).hexdigest()
def read(path):return json.loads(Path(path).read_text())
def save(path,value):
 path=Path(path);temporary=Path(str(path)+'.tmp');temporary.write_text(json.dumps(value,indent=2)+'\n');temporary.replace(path)
source=read(prefix+'-input.json')
metadata={**source['metadata'],'binarySha256':{k:digest(v) for k,v in binaries.items()},'inputSha256':digest(prefix+'-input.json'),'method':'Full AIPlayer.GetBestMove, exact UCI history, each side in a fresh process; alternating order; whole job uses authenticated idle supervisor; complete pairs committed atomically.'}
mp=Path(prefix+'-metadata.json')
if mp.exists():assert read(mp)==metadata
else:save(mp,metadata)
records=[]
for index,case in enumerate(source['cases']):
 checkpoint=Path(f'{prefix}-{index}-pair.json')
 if checkpoint.exists():
  pair=read(checkpoint);assert pair['case']==case and pair['binarySha256']==metadata['binarySha256']
  records.append(pair);continue
 pair={'index':index,'case':case,'binarySha256':metadata['binarySha256']}
 for side in (['before','after'] if index%2==0 else ['after','before']):
  assert digest(binaries[side])==metadata['binarySha256'][side]
  result=subprocess.run([binaries[side]],input=json.dumps(case),capture_output=True,text=True,timeout=20)
  Path(f'{prefix}-{index}-{side}.txt').write_text(result.stdout+result.stderr)
  if result.returncode:raise RuntimeError(f'Policy probe failed {index} {side}: {result.returncode}')
  pair[side]=json.loads(result.stdout)
 assert pair['before']['fen']==pair['after']['fen']
 save(checkpoint,pair);records.append(pair)
 if index%15==0 or pair['before']['move']!=pair['after']['move']:
  print('Pair',index+1,'of',len(source['cases']),case['id'],pair['before']['move'],pair['after']['move'],flush=True)
for side in binaries:
 positions=[{'fen':r[side]['fen'],'tag':r['case']['id'],'threads':[{'threads':4,'summary':{'move':r[side]['move'],'depth':r[side]['depth']}}]} for r in records]
 save(prefix+'-'+side+'.json',{'metadata':metadata,'positions':positions})
print('Scoring completed opening-policy pairs',len(records),flush=True)
with open(prefix+'-common.txt','w') as output:
 result=subprocess.run(['python3','/tmp/chess-oct26-opening-policy-common-rescore.py',prefix+'-before.json',prefix+'-after.json',prefix+'-common.json'],stdout=output,stderr=subprocess.STDOUT)
if result.returncode:raise RuntimeError('Common opening-policy scoring failed')
rows=read(prefix+'-common.json')
for budget in [500,3000]:
 for label,include in [('recorded',lambda r:not r['case']['synthetic']),('all',lambda r:True)]:
  selected=[row for record,row in zip(records,rows) if record['case']['budgetMs']==budget and include(record)]
  for side in binaries:
   losses=[r[side+'Loss'] for r in selected]
   print('budget',budget,label,side,'positions',len(losses),'cappedMean',round(sum(min(x,1000) for x in losses)/len(losses),2),'errors>=100',sum(x>=100 for x in losses),'errors>=200',sum(x>=200 for x in losses),'mate-scale',sum(x>=10000 for x in losses),flush=True)
print('Opening-policy comparison completed; no deployment performed.',flush=True)

