import json,subprocess
from pathlib import Path
sources=['testdata/lichess_2026_10_26_post_pawnless_games.json','testdata/lichess_2026_10_26_post_build_games.json']
positions={}
ids=[]
for source in sources:
 for game in json.loads(Path(source).read_text()):
  if game.get('variant')!='standard' or game['id'] in ids:continue
  ids.append(game['id'])
  text=' '.join(game['moves'].split()[:3])
  replay=subprocess.run(['/tmp/chess-oct26-before-preference-capture','san-fens'],input=text,text=True,capture_output=True,check=True)
  moves=[]
  for line in replay.stdout.splitlines():
   parts=line.split(' | ')
   if len(parts)==4:moves.append(parts[2])
  side='white' if game['players']['white'].get('user',{}).get('id')=='vadbot' else 'black'
  for turn in range(2):
   count=2*turn+(side=='black')
   if count>len(moves):continue
   prefix=moves[:count]
   key=' '.join(prefix)
   entry=positions.setdefault(key,{'prefix':prefix,'sources':[],'synthetic':False})
   entry['sources'].append({'gameId':game['id'],'botSide':side,'turn':turn,'dataset':source})
for name,prefix in [
 ('Englund',['d2d4','e7e5']),
 ('KingsGambit',['e2e4','e7e5','f2f4']),
