 ('Reti',['g1f3','d7d5','c2c4']),
 ('AlekhinePawnOffer',['e2e4','g8f6','f2f4']),
]:
 key=' '.join(prefix)
 if key not in positions:positions[key]={'prefix':prefix,'sources':[{'control':name}],'synthetic':True}
