   cases.append({**position,'id':f'opening-{number}-budget{budget}-book{opening}','opening':opening,'budgetMs':budget})
result={'metadata':{'sourceGames':ids,'sourceDatasets':sources,'uniquePrefixes':len(positions),'cases':len(cases),'budgetMs':[500,3000],'openingStates':[-1,0,1],'purpose':'Actual early-game prefixes plus explicit gambit controls; each policy call receives complete move history.'},'cases':cases}
Path('/tmp/chess-oct26-opening-policy-input.json').write_text(json.dumps(result,indent=2)+'\n')
print(json.dumps(result['metadata']))

